 if(n.includes('مواد')&&n.includes('اعمار')){if(n.includes('خشب'))return 'مواد الإعمار — الخشب';if(n.includes('رخام'))return 'مواد الإعمار — الرخام والجرانيت';if(/المنيوم|المينيوم|الالمنيوم/.test(n))return 'مواد الإعمار — الألمنيوم';return 'مواد الإعمار'}
