function updatePrintSetting(key,value,region=state.region){saved.print.regions[region]=Object.assign({},printSettings(region),{[key]:value,_partnerVisibilityConfigured:true,_reportLayoutVersion:3})}
const regionReports=()=>reportRecords().filter(r=>r.region===state.region);
function currentReport(){const rs=regionReports();const source=rs.find(r=>r.id===state.reportId)||rs.at(-1);if(!source)return null;return Object.assign({},source,{header:Object.assign({},source.header,saved.headers[source.id]||{})})}
const vkey=(r,v)=>r.id+':'+v.id;
function inferGender(name){const n=norm(name);if(/بنات|طالبات/.test(n))return 'girls';if(/بنين|للبنين/.test(n))return 'boys';return 'unspecified'}
function visitData(r,v){
 const key=vkey(r,v),d=Object.assign({},v,saved.visits[key]||{});d._key=key;
 d.gender=['boys','girls','unspecified'].includes(d.gender)?d.gender:inferGender(d.schoolName);
 const positions={...d.imagePositions};d.images=(d.images||[]).map(url=>{const next=driveImageURL(url);if(d.imagePositions?.[url])positions[next]=d.imagePositions[url];return next});d.imagePositions=positions;
 const factoryKey=fkey(r.region,d.factory);
 const local=saved.factories[factoryKey]||Object.entries(saved.factories).find(([k])=>k.startsWith(r.region+':')&&fkey(r.region,k.slice(r.region.length+1))===factoryKey)?.[1];
 const shared=regionPresentation(r.region).factories?.[factoryKey];
 const logoHidden=local?.logoHidden===true||shared?.logoHidden===true;
 d.factoryLogo=logoHidden?'':driveImageURL(local?.url||shared?.url||d.factoryLogo||registry.get(factoryKey)?.url);
 return d;
}
function orderedRawVisits(r){const raw=Array.isArray(r?.visits)?r.visits:[],order=Array.isArray(saved.orders?.[r.id])?saved.orders[r.id].map(String):[];if(!order.length)return raw;const byId=new Map(raw.map(v=>[String(v.id),v])),used=new Set(),ordered=[];for(const id of order){const visit=byId.get(id);if(visit){ordered.push(visit);used.add(id)}}return ordered.concat(raw.filter(v=>!used.has(String(v.id))))}
const visits=r=>orderedRawVisits(r).map(v=>visitData(r,v));
function saveVisitOrder(r,keys){if(!r)return false;const ids=new Map(visits(r).map(v=>[v._key,String(v.id)]));saved.orders[r.id]=keys.map(key=>ids.get(key)).filter(Boolean);if(editableReport(r.id))scheduleReportSync('تم حفظ ترتيب الزيارات.');else persist('تم حفظ ترتيب الزيارات على هذا المتصفح.');render(true);return true}
function moveVisitBy(key,delta){const r=currentReport();if(!r)return;const keys=visits(r).map(v=>v._key),index=keys.indexOf(key),target=index+delta;if(index<0||target<0||target>=keys.length)return;[keys[index],keys[target]]=[keys[target],keys[index]];saveVisitOrder(r,keys)}
function reorderVisitCards(sourceKey,targetKey){const r=currentReport();if(!r||sourceKey===targetKey)return;const keys=visits(r).map(v=>v._key),from=keys.indexOf(sourceKey),to=keys.indexOf(targetKey);if(from<0||to<0)return;const [item]=keys.splice(from,1);keys.splice(to,0,item);saveVisitOrder(r,keys)}
const genderLabel=g=>g==='boys'?'بنين':g==='girls'?'بنات':'زيارة مدرسية';
function persist(message){try{localStorage.setItem(STORE,JSON.stringify(saved));if(message)toast(message);return true}catch(e){toast('تعذر الحفظ في هذا المتصفح. صدّر نسخة الإعدادات للاحتفاظ بالتعديلات.');return false}}
let toastTimer;function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
function sharedTheme(){const latest=reportRecords().filter(r=>r.presentation?.theme).sort((a,b)=>String(b.presentation.updatedAt||b.updatedAt||'').localeCompare(String(a.presentation.updatedAt||a.updatedAt||'')))[0]?.presentation?.theme;return {...defaultTheme(),...latest}}
function applyTheme(){const t=editingReport()?saved.theme:sharedTheme();const root=document.documentElement;const props={'--boys':t.boys,'--girls':t.girls,'--bg1':t.bg1,'--bg2':t.bg2,'--bg3':t.bg3,'--radius':t.radius+'px','--photo-height':t.photoHeight+'px','--card-gap':t.gap+'px','--logo-size':t.logoSize+'px','--logo-control-size':t.logoSize+'px','--visit-logo-scale':(Math.max(40,Math.min(190,Number(t.logoSize)||168))/190*100)+'%','--web-partner-box-width':(Math.max(70,Math.min(220,Number(t.webPartnerBoxSize)||120)))+'px','--web-partner-scale':(Number(t.partnerLogoScale)||95)+'%','--font-scale':t.fontScale/100,'--factory-font-scale':(Number(t.factoryFontScale)||100)/100,'--columns':t.columns,'--motion-speed':t.speed+'s','--network-opacity':t.networkOpacity/100};for(const[k,v]of Object.entries(props))root.style.setProperty(k,v);Object.assign(root.dataset,{motion:t.motion?'on':'off',network:t.network?'on':'off',columns:t.columns,photoLayout:t.photoLayout,showFactories:t.showFactories?'on':'off',showCategories:t.showCategories?'on':'off'});updateNetwork()}
