function mapView(){const pts=regions.map(r=>projectPoint(r.lon,r.lat));const route=(a,b)=>'M'+pts[a].x+','+pts[a].y+'Q'+((pts[a].x+pts[b].x)/2)+','+(Math.min(pts[a].y,pts[b].y)-40)+' '+pts[b].x+','+pts[b].y;return '<div class="map-wrap" aria-label="خريطة السعودية والمناطق الأربع"><svg class="saudi-map" viewBox="0 0 800 620" role="img" aria-label="حدود المملكة العربية السعودية"><defs><linearGradient id="land-gradient" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#7282cd" stop-opacity=".32"/><stop offset="1" stop-color="#283674" stop-opacity=".68"/></linearGradient><pattern id="land-dots" width="13" height="13" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".8" fill="#d3deff" opacity=".22"/></pattern><clipPath id="land-clip"><path d="'+mapPath+'"/></clipPath></defs><path class="map-outline" d="'+mapPath+'"/><path class="map-land" d="'+mapPath+'"/><path d="'+mapPath+'" fill="url(#land-dots)"/><g clip-path="url(#land-clip)"><path class="map-route" d="'+route(0,2)+'"/><path class="map-route" d="'+route(1,2)+'"/><path class="map-route" d="'+route(2,3)+'"/></g></svg>'+regions.map((r,i)=>{const p=pts[i];return '<button class="map-node" data-action="region" data-region="'+r.id+'" style="left:'+p.x/8+'%;top:'+(p.y+24)/6.2+'%" aria-label="تقارير '+r.name+'"><span class="node-dot"></span><span class="node-label">'+r.name+'</span></button>'}).join('')+'</div>'}
