function factoryLogo(url){return '<div class="factory-logo"><span class="logo-fallback">'+ico('factory')+'</span>'+(url?'<img data-logo src="'+esc(url)+'" alt="شعار المصنع" loading="lazy" decoding="async">':'')+'</div>'}
function photoPosition(v,url){const value=v.imagePositions?.[url];if(value&&typeof value==='object')return {x:Math.max(0,Math.min(100,Number(value.x)||0)),y:Math.max(0,Math.min(100,Number(value.y)||0))};return {x:50,y:value==='top'?0:value==='bottom'?100:50}}
