function metricIcon(kind){const paths={
 factory:'<path d="M3 21V9l6 3V7l7 4V3h5v18H3Z"/><path d="M7 16h1m4 0h1m4 0h1M7 19h1m4 0h1m4 0h1"/>',
 users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-17a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 4v3"/>',
 beneficiaries:'<path d="M12 20 4.5 13a5 5 0 0 1 7.5-6.5A5 5 0 0 1 19.5 13L12 20Z"/><path d="M7 12h3l2-4 2 7 2-3h2"/>',
 award:'<path d="M8 3h8v5a4 4 0 0 1-8 0V3Z"/><path d="M8 5H4v2a4 4 0 0 0 4 4m8-6h4v2a4 4 0 0 1-4 4m-4 1v5m-4 4h8m-6-4h4v4"/>'};return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[kind]||paths.users)+'</svg>'}
