function stats(r){return '<div class="stats-row">'+statBox('الزيارات الميدانية',r.visits.length,'factory')+statBox('المشاركون في الزيارات',visits(r).reduce((n,v)=>n+(Number(v.participants)||0),0),'users')+statBox('إجمالي المستفيدين',r.stats.totalBeneficiaries,'beneficiaries')+statBox('المسجلون بالجائزة',r.stats.totalRegistered,'award')+'</div>'}
function awardCategories(r){return [{key:'discoverer',name:'فئة المكتشف',value:r.stats.discovererCategory},{key:'creative',name:'فئة المبدع',value:r.stats.creativeCategory},{key:'ambassador',name:'فئة السفير',value:r.stats.ambassadorCategory},{key:'artist',name:'فئة الفنان',value:r.stats.artistCategory}]}
function categories(r){const data=awardCategories(r);return '<section class="categories">'+stats(r)+'<div class="categories-heading"><h3>فئات الجائزة</h3><small>المشاركات المسجلة في التقرير</small></div><div class="category-grid">'+data.map(x=>'<div class="category-card">'+categoryIcon(x.key)+'<b class="category-num">'+fmt(x.value)+'</b><span class="category-name">'+x.name+'</span></div>').join('')+'</div></section>'}
function reportFactories(region){const seen=new Set();return factories(region).filter(f=>f.region===region&&f.visible!==false&&f.url).filter(f=>{let logo=driveImageURL(f.url);try{const u=new URL(logo,location.origin);u.searchParams.delete('token');u.searchParams.delete('alt');logo=u.href}catch{}let name=norm(f.name);if(name.startsWith('مواد الاعمار'))name='مواد الاعمار';if(name.includes('تمر'))name=/مول|مون/.test(name)?'تمر مولنكلي':'تمر';if(seen.has(logo)||seen.has(name))return false;seen.add(logo);seen.add(name);return true})}
function webPartnerSize(){return Math.max(70,Math.min(220,Number(saved.theme.webPartnerBoxSize)||120))}
function directPartnerControl(p){return '<span class="direct-partner-control"><b>'+esc(p.name||'الشريك')+'</b><span><button type="button" data-size-partner="'+esc(p.id)+'" data-size-delta="-5" aria-label="تصغير الشعار">−</button><input type="number" min="25" max="100" value="'+partnerScale(p)+'" data-partner-size="'+esc(p.id)+'" aria-label="حجم '+esc(p.name||'الشعار')+' بالنسبة المئوية"><span>%</span><button type="button" data-size-partner="'+esc(p.id)+'" data-size-delta="5" aria-label="تكبير الشعار">+</button></span></span>'}
function webPartnerToolbar(){return '<div class="web-partner-toolbar"><div><b>حجم شعارات أسفل تقرير الويب</b><small>حجم الجميع بالبكسل. تحت كل شعار تحكم منفصل بنسبة حجمه.</small></div><div class="web-size-inputs"><button type="button" data-web-size-delta="-10" aria-label="تصغير جميع الشعارات">−</button><input type="range" min="70" max="220" value="'+webPartnerSize()+'" data-web-partner-size aria-label="حجم جميع شعارات الويب"><input type="number" min="70" max="220" value="'+webPartnerSize()+'" data-web-partner-size aria-label="حجم شعارات الويب بالبكسل"><span>px</span><button type="button" data-web-size-delta="10" aria-label="تكبير جميع الشعارات">+</button></div></div>'}
function updateWebPartnerSize(value){const size=Math.max(70,Math.min(220,Number(value)||120));saved.theme.webPartnerBoxSize=size;applyTheme();document.querySelectorAll('[data-web-partner-size]').forEach(input=>input.value=size);clearTimeout(saveTimer);saveTimer=setTimeout(()=>{persist();scheduleReportSync('تم حفظ حجم شعارات الويب للزوار.')},350)}
function factoryFooter(region){return (state.view==='admin'?webPartnerToolbar():'')+partnerStrip(region,'web-report-partners'+(state.view==='admin'?' partners-editable':''),'شركاء النجاح · '+regionById(region).name)}
function regionOptions(){return regions.map(r=>'<option value="'+r.id+'" '+(r.id===state.region?'selected':'')+'>'+r.name+'</option>').join('')}
function reportOptions(){const current=currentReport();return regionReports().slice().reverse().map(r=>'<option value="'+r.id+'" '+(current&&r.id===current.id?'selected':'')+'>'+esc(reportPeriod({...r,header:{...r.header,...saved.headers[r.id]}}).week)+'</option>').join('')}
function filteredVisits(r){return visits(r).filter(v=>(state.gender==='all'||v.gender===state.gender)&&(!state.search||norm(v.schoolName+' '+v.factory+' '+v.date).includes(norm(state.search))))}
function visitsMarkup(r){const all=filteredVisits(r);return all.length?all.map((v,i)=>visitCard(v,i)).join(''):'<div class="empty"><h2>لا توجد زيارات مطابقة</h2><p>جرّب اسم مدرسة أو مصنع آخر، أو غيّر تصنيف الزيارات.</p></div>'}
function report(){const r=currentReport();return '<main class="report-shell page"><div class="report-heading"><div class="breadcrumb"><button data-action="home">خريطة المناطق</button>'+ico('chevron')+'<span>'+area().name+'</span></div><div class="report-heading-row"><div><h1>تقارير '+area().name+'</h1></div><div class="heading-buttons"><select data-select="region" class="region-select" aria-label="المنطقة">'+regionOptions()+'</select>'+(r?'<button class="btn btn-white" data-action="print-preview">'+ico('download')+'معاينة التقرير</button>':'')+'</div></div></div>'+(r?'<nav class="week-nav" aria-label="أسابيع التقارير">'+regionReports().slice().reverse().map(w=>'<button class="week-tab '+(w.id===r.id?'active':'')+'" data-action="week" data-id="'+w.id+'" '+(w.id===r.id?'aria-current="true"':'')+'>'+esc(reportPeriod({...w,header:{...w.header,...saved.headers[w.id]}}).week)+'</button>').join('')+'</nav>'+banner(r)+'<div class="section-row"><div><h2>الزيارات الميدانية</h2><small id="result-count">'+fmt(filteredVisits(r).length)+' زيارة</small></div><div class="filters"><label class="search">'+ico('search')+'<input id="visit-search" type="search" placeholder="ابحث عن مدرسة أو مصنع" value="'+esc(state.search)+'" aria-label="البحث في الزيارات"></label><select id="gender-filter" class="filter-select" aria-label="تصنيف الزيارات"><option value="all">جميع الزيارات</option><option value="boys" '+(state.gender==='boys'?'selected':'')+'>بنين</option><option value="girls" '+(state.gender==='girls'?'selected':'')+'>بنات</option></select></div></div><div class="visits" id="visit-results">'+visitsMarkup(r)+'</div>'+categories(r)+factoryFooter(state.region):'<div class="empty" style="margin-top:35px">'+ico('file')+'<h2>قريبًا، قصص جديدة من '+area().name+'</h2><p>لا توجد تقارير منشورة حاليًا.</p><button class="btn btn-glass" data-action="home">العودة للخريطة</button></div>')+'</main>'}
const field=(label,value,attr,type='text')=>'<label class="field"><span>'+label+'</span><input type="'+type+'" '+attr+' value="'+esc(value)+'" '+(type==='number'?'min="0" step="1"':'')+'></label>';
const textarea=(label,value,attr)=>'<label class="field textarea-field"><span>'+label+'</span><textarea '+attr+'>'+esc(value)+'</textarea></label>';
const color=(label,key)=>'<label class="color-row">'+label+'<input type="color" data-theme="'+key+'" value="'+saved.theme[key]+'" aria-label="'+label+'"></label>';
const range=(label,key,min,max,unit)=>'<label class="field"><span>'+label+'<output id="out-'+key+'">'+saved.theme[key]+unit+'</output></span><input type="range" data-theme="'+key+'" min="'+min+'" max="'+max+'" value="'+saved.theme[key]+'" data-unit="'+unit+'" aria-label="'+label+'"></label>';
const toggle=(label,key)=>'<label class="switch-row"><span>'+label+'</span><input type="checkbox" data-theme="'+key+'" '+(saved.theme[key]?'checked':'')+'></label>';
function choices(key,list){return '<div class="choice-row">'+list.map(([value,label])=>'<button data-action="theme-choice" data-key="'+key+'" data-value="'+value+'" class="'+(String(saved.theme[key])===String(value)?'active':'')+'">'+label+'</button>').join('')+'</div>'}
function designControls(){return '<section class="control-group"><h3>هوية البطاقات</h3>'+color('زيارات البنين · أزرق','boys')+color('زيارات البنات · نهدي','girls')+'<p class="control-note">التصنيف غير المحدد يظهر بلون محايد إلى أن تتم مراجعته.</p></section><section class="control-group"><h3>الخلفية والحركة</h3>'+color('بداية التدرج','bg1')+color('منتصف التدرج','bg2')+color('نهاية التدرج','bg3')+toggle('الحركة والتدرج المتغير','motion')+toggle('الشبكة والنقاط المتحركة','network')+range('وضوح الشبكة','networkOpacity',35,100,'%')+range('مدة دورة الألوان','speed',12,50,' ث')+'</section><section class="control-group"><h3>تصميم الزيارات</h3>'+choices('columns',[[1,'عمود واحد'],[2,'عمودان']])+'<p class="control-note">العمودان للشاشات الواسعة؛ عرض الموبايل يبقى عمودًا واحدًا.</p>'+range('استدارة البطاقات','radius',6,32,'px')+range('المسافة بين البطاقات','gap',12,42,'px')+range('حجم اسم المدرسة','fontScale',85,120,'%')+range('حجم اسم المصنع','factoryFontScale',70,180,'%')+range('حجم شعار المصنع داخل كرت الزيارة','logoSize',40,190,'px')+range('حجم شعارات شركاء المنطقة','partnerLogoScale',35,100,'%')+'<p class="control-note">سلايدر المصنع يغيّر شعار كرت الزيارة، وسلايدر الشركاء يغيّر شعارات فوتر الويب. راجع النتيجة مباشرة، ثم احفظ التقرير للزوار.</p></section><section class="control-group"><h3>عرض الصور</h3>'+choices('photoLayout',[['row','صف صور'],['mosaic','شبكة 2 × 2']])+range('ارتفاع الصورة','photoHeight',100,250,'px')+toggle('عرض مصانع المنطقة','showFactories')+toggle('عرض فئات الجائزة','showCategories')+'<button class="btn btn-soft btn-small full-width" data-action="reset-theme">استعادة تنسيق الهوية</button></section>'}
function emptyReportStats(){return {ambassadorCategory:0,tvInterviews:0,tweets:0,videos:0,posts:0,discovererCategory:0,creativeCategory:0,totalBeneficiaries:0,totalRegistered:0,artistCategory:0}}
function editableReport(id){return saved.reports.find(r=>r&&r.id===id)||null}
function regionById(id){return regions.find(region=>region.id===id)||regions[0]}
function detectedReportRegion(report){const text=String(saved.intakes[report?.id]||'')+' '+String(report?.header?.region||'')+' '+String(report?.header?.title||'');for(const region of regions){if(text.includes(region.name)||text.toLowerCase().includes(region.en.toLowerCase()))return region.id}return ''}
function reportManagementControls(r){const suggested=detectedReportRegion(r),wrong=suggested&&suggested!==r?.region;return '<section class="control-group"><h3>إدارة التقرير</h3>'+(wrong?'<div class="report-warning"><b>تنبيه: محتوى التقرير يذكر '+esc(regionById(suggested).name)+'</b><span>التقرير محفوظ حاليًا تحت '+esc(regionById(r.region).name)+'. يمكنك نقله قبل متابعة التعديل.</span><button class="btn btn-soft btn-small" data-action="move-report-suggested" data-region="'+esc(suggested)+'">نقل إلى '+esc(regionById(suggested).name)+'</button></div>':'')+'<label class="field"><span>نقل التقرير إلى منطقة أخرى</span><select id="move-report-region">'+regions.map(region=>'<option value="'+region.id+'" '+(region.id===r.region?'selected':'')+'>'+region.name+'</option>').join('')+'</select></label><button class="btn btn-soft btn-small full-width" data-action="move-report">نقل التقرير</button><button class="btn btn-danger btn-small full-width" style="margin-top:8px" data-action="delete-report">حذف التقرير</button><p class="control-note" style="margin-top:9px">النقل والحذف يُحفظان على المنصة نفسها، ولن يعود التقرير بعد تحديث الصفحة.</p></section>'}
function newReportControls(){return '<section class="control-group new-report-control"><h3>إضافة تقرير جديد</h3><p class="control-note">يمكن إنشاء تقرير مستقل لأي منطقة، ثم تشغيل التوزيع التلقائي من تبويب «التوزيع» لإضافة الزيارات والصور.</p>'+field('عنوان الأسبوع','','id="new-report-week"')+field('الفترة الزمنية','','id="new-report-date"')+'<button class="btn btn-dark btn-small full-width" data-action="create-report">'+ico('file')+'إنشاء تقرير '+esc(area().name)+'</button><p class="control-note" style="margin-top:9px">بعد التوزيع اضغط «حفظ التقرير للزوار» حتى تظهر الصور والشعارات وإعدادات الطباعة على الأجهزة الأخرى.</p></section>'}
function aiSettingsControls(){return '<section class="control-group"><h3>ربط GitHub وGoogle Drive</h3><p class="control-note">اربط GitHub من الشريط أعلى اللوحة لحفظ التقارير والصور. لجلب صور Drive، أدخل مفتاح Google Drive API وشارك مجلد الصور مع «أي شخص لديه الرابط». يُحفظ المفتاح في هذا المتصفح. لمسحه اضغط «مسح مفاتيح الربط» أعلى اللوحة.</p><label class="field">مفتاح Google Drive<input id="drive-key" type="password" autocomplete="off" placeholder="أدخل المفتاح هنا"></label><button class="btn btn-dark btn-small full-width" data-action="save-ai-settings">حفظ مفتاح Drive</button><p id="ai-settings-status" role="status" class="control-note">'+(window.FI_DRIVE?.connected()?'مفتاح Drive محفوظ في هذا المتصفح.':'Drive يحتاج مفتاح API. فعّل Google Drive API واسمح بالعنوان https://azlartr.github.io/* في إعدادات المفتاح.')+'</p></section>'}
function generalControls(r){const totalReports=reportRecords().length,totalVisits=reportRecords().reduce((n,x)=>n+(Array.isArray(x.visits)?x.visits.length:0),0);return aiSettingsControls()+'<section class="control-group"><h3>بيانات التقرير</h3>'+field('اسم الأسبوع / التقرير (كما تريد)',reportPeriod(r).week,'data-header="weekTitle" placeholder="الأسبوع السابع" maxlength="120"')+field('الفترة الزمنية',r.header.dateRange,'data-header="dateRange" placeholder="من 1 أكتوبر إلى 4 أكتوبر 2026"')+field('أيام الفترة (اختياري، تُستخرج من التاريخ)',r.header.dayRange||'','data-header="dayRange" placeholder="الخميس إلى الأحد"')+'<div class="admin-message">التوزيع يحفظ الزيارات على الخادم عند نجاحه. بعد تعديل الشعارات أو الطباعة اضغط «حفظ التقرير للزوار» ليقرأها الجميع.</div></section>'+reportManagementControls(r)+newReportControls()+'<section class="control-group"><h3>مراجعة البيانات</h3><p class="control-note">الأرشيف يحتوي على '+fmt(totalReports)+' تقريرًا و'+fmt(totalVisits)+' زيارة. يحتفظ كل تقرير ببياناته الأصلية، وتُطبق التعديلات فوقها.</p><div class="source-summary"><div><b>'+fmt(visits(r).filter(v=>v.gender==='unspecified').length)+'</b><span>زيارات تحتاج تحديد النوع</span></div><div><b>'+fmt(factories(state.region).length)+'</b><span>مصانع المنطقة</span></div></div><button style="margin-top:12px" class="btn btn-soft btn-small full-width" data-action="review-gender">مراجعة التصنيف</button></section><section class="control-group"><h3>نسخة من الإعدادات</h3><p class="control-note">تصدير الألوان وشعارات المناطق والتعديلات المحلية للاحتفاظ بها.</p><button class="btn btn-dark btn-small full-width" data-action="export-settings">'+ico('download')+'تصدير الإعدادات</button></section>'}
function selectedVisit(r){const list=visits(r);return list.find(v=>v._key===state.selectedVisit)||list[0]}
function visitImageControls(v){return [0,1,2,3].map(i=>{const url=v.images[i]||'',position=photoPosition(v,url).y===0?'top':photoPosition(v,url).y===100?'bottom':'center';return '<div class="visit-image-control">'+(url?'<img class="visit-image-thumb" src="'+esc(url)+'" style="object-position:'+photoStyle(v,url)+'" alt="الصورة '+(i+1)+'">':'<p class="control-note">الصورة '+(i+1)+' غير مرفقة</p>')+field('رابط الصورة '+(i+1),url,'data-visit-image="'+i+'"','url')+'<label class="field"><span>موضع الصورة '+(i+1)+'</span><select data-visit-position="'+i+'">'+[['top','فوق'],['center','وسط'],['bottom','تحت']].map(([value,label])=>'<option value="'+value+'" '+(value===position?'selected':'')+'>'+label+'</option>').join('')+'</select></label><label class="upload">'+ico('upload')+(url?'استبدال الصورة':'رفع صورة يدويًا')+'<input data-visit-upload="'+i+'" type="file" accept="image/png,image/jpeg,image/webp,image/avif"></label></div>'}).join('')}
function visitControls(r){const v=selectedVisit(r),editable=!!editableReport(r.id),addButton=editable?'<button class="btn btn-dark btn-small full-width" data-action="add-visit">'+ico('school')+'إضافة زيارة</button>':'<p class="control-note">هذا تقرير من الأرشيف الأساسي؛ يمكن تعديل بياناته، وإضافة الزيارات ستكون متاحة للتقارير المنشأة من الإدارة.</p>';if(!v)return '<section class="control-group"><h3>زيارات التقرير</h3><p class="control-note">لا توجد زيارات في هذا التقرير بعد.</p>'+addButton+'</section>';return '<section class="control-group"><h3>بيانات الزيارة</h3><label class="field"><span>اختر زيارة</span><select id="editor-visit">'+visits(r).map((x,i)=>'<option value="'+esc(x._key)+'" '+(x._key===v._key?'selected':'')+'>'+(i+1)+'. '+esc(x.schoolName)+'</option>').join('')+'</select></label>'+field('اسم المدرسة',v.schoolName,'data-visit-field="schoolName"')+field('اسم المصنع',v.factory,'data-visit-field="factory"')+'<div class="field-pair">'+field('عدد المشاركين',v.participants,'data-visit-field="participants"','number')+field('تاريخ الزيارة',v.date,'data-visit-field="date"')+'</div><label class="field"><span>التصنيف ولون البطاقة</span><select data-visit-field="gender"><option value="unspecified" '+(v.gender==='unspecified'?'selected':'')+'>يحتاج تحديد</option><option value="boys" '+(v.gender==='boys'?'selected':'')+'>بنين · أزرق</option><option value="girls" '+(v.gender==='girls'?'selected':'')+'>بنات · نهدي</option></select></label><p class="control-note">شعار المصنع يُدار مرة واحدة من تبويب «المصانع» ويظهر في الزيارات تلقائيًا.</p>'+addButton+'</section><section class="control-group"><h3>صور الزيارة</h3><p class="control-note">يمكن استبدال أي صورة برابط صورة مباشر. تبقى أصول الأرشيف محفوظة.</p>'+visitImageControls(v)+'</section>'}
function partnerControls(){const list=partnersFor(state.region);return '<section class="control-group"><h3>شركاء نجاح '+area().name+'</h3><p class="control-note">هذه قائمة شركاء المنطقة الثابتة. تظهر في فوتر الويب والصفحات الداخلية لجميع أسابيع المنطقة.</p>'+field('رابط مجلد شعارات الشركاء في Google Drive',saved.partnerSources[state.region]||'','id="partner-source-folder"','url')+'<button class="btn btn-dark btn-small full-width" data-action="import-partner-drive">جلب الشعارات وحفظها للمنطقة</button><label class="upload full-width" style="margin-top:8px">رفع مجلد الشعارات من الجهاز<input id="local-partner-folder" type="file" webkitdirectory multiple accept="image/png,image/jpeg,image/webp,image/avif"></label><div class="admin-message" id="partner-import-status" role="status">الرابط وحده لا يجلب الصور. اضغط الزر لاستيرادها وحفظها لجميع تقارير هذه المنطقة.</div>'+(list.length?'<div class="partner-registry">'+list.map((p,i)=>'<div class="partner-row"><span class="partner-row-logo"><img data-logo src="'+esc(p.url)+'" alt="'+esc(p.name||'شريك نجاح')+'"></span><b>'+esc(p.name||('شريك نجاح '+(i+1)))+'</b><button class="remove-partner" data-action="remove-partner" data-partner-id="'+esc(p.id)+'" aria-label="حذف '+esc(p.name||'الشريك')+'">'+ico('close')+'</button>'+partnerSizeControl(p)+'</div>').join('')+'</div>':'<p class="control-note partner-empty">لا توجد شعارات شركاء بعد لهذه المنطقة.</p>')+field('اسم شريك النجاح','','id="new-partner-name"')+'<label class="upload">'+ico('upload')+'رفع شعار الشريك<input id="new-partner-upload" type="file" accept="image/png,image/jpeg,image/webp,image/avif"></label></section>'}
function updateMatchingPartnerLogo(key,url){const region=key.split(':')[0],list=partnersFor(region);saved.partners[region]=list.map(p=>fkey(region,p.name)===key?{...p,url}:p);saved.partnerRegistryConfigured[region]=true}
function factoryControls(){const partnerList=partnersFor(state.region);return '<section class="control-group"><h3>مصانع '+area().name+'</h3><p class="control-note">ارفع الشعار مرة واحدة. يُستخدم في كروت الزيارات. اضغط «حفظ التقرير للزوار» بعد الانتهاء ليظهر على الأجهزة الأخرى. هذه الشعارات لا تدخل في فوتر PDF؛ الفوتر يستخدم شركاء النجاح فقط.</p>'+factories(state.region).map(f=>'<div class="registry-row"><div class="registry-top">'+(f.url?'<img data-logo src="'+esc(driveImageURL(f.url))+'" alt="">':ico('factory'))+'<span><b>'+esc(f.name)+'</b><small>'+fmt(f.visits||0)+' زيارات في أرشيف المنطقة</small></span></div><div class="registry-actions"><label class="upload">'+ico('upload')+'رفع الشعار<input type="file" data-upload-factory="'+esc(f.key)+'" accept="image/png,image/jpeg,image/webp,image/avif"></label><label><input type="checkbox" data-factory-visible="'+esc(f.key)+'" '+(f.visible!==false?'checked':'')+'> يظهر أسفل التقرير</label></div>'+(()=>{const partner=partnerList.find(p=>p.url===driveImageURL(f.url)||norm(p.name)===norm(f.name));return partner?partnerSizeControl(partner):''})()+'</div>').join('')+'</section><section class="control-group"><h3>إضافة مصنع للمنطقة</h3>'+field('اسم المصنع','','id="new-factory-name"')+'<label class="upload">'+ico('upload')+'اختر الشعار وأضف المصنع<input id="new-factory-upload" type="file" accept="image/png,image/jpeg,image/webp,image/avif"></label><p class="control-note" style="margin-top:9px">يدعم PNG وJPG وWebP. تتذكر الإدارة شعار كل منطقة بشكل مستقل.</p></section>'+partnerControls()}
function distributionControls(r){const source=saved.sources[state.region]||'',intake=saved.intakes[r.id]||'',info=saved.automation[r.id]||null,warnings=Array.isArray(info?.warnings)?info.warnings:[],runNote=info?('<div class="admin-message">آخر تشغيل: '+fmt(info.matchedImages||0)+' صور مرتبطة بالكروت'+(info.unmatchedImages?' · '+fmt(info.unmatchedImages)+' صور تحتاج مراجعة':'')+(warnings.length?' · توجد ملاحظات أدناه':'')+'</div>'+(warnings.length?'<div class="automation-warnings"><b>ملاحظات المطابقة الذكية</b><ul>'+warnings.map(item=>'<li>'+esc(item)+'</li>').join('')+'</ul></div>':'') ):'';return '<section class="control-group"><h3>إنشاء الزيارات تلقائيًا</h3><p class="control-note">هذا هو المكان المخصص للتوزيع: الصق التقرير، أضف رابط مجلد الصور، ثم اضغط الزر. لن يُنشئ النظام أي كروت أو يحفظ تقريرًا جديدًا بمجرد لصق النص.</p>'+textarea('نص التقرير المكتوب',intake,'id="report-intake" placeholder="الأسبوع، الفترة، اسم المدرسة، اسم المصنع، التاريخ، عدد المشاركين…"')+field('رابط مجلد الصور في Google Drive',source,'id="source-folder"','url')+'<button class="btn btn-dark btn-small full-width automation-run" data-action="auto-distribute" '+(autoBusy?'disabled':'')+'>'+ico('spark')+(autoBusy?'جارٍ التحليل والتوزيع…':'تحليل التقرير وإنشاء الكروت')+'</button><button class="btn btn-soft btn-small full-width" data-action="rematch-drive-images">'+ico('photo')+'إعادة جلب صور Drive فقط</button>'+'<label class="upload full-width" style="margin-top:8px">'+ico('upload')+'رفع مجلد الصور وتوزيعه تلقائيًا<input id="local-photo-folder" type="file" webkitdirectory multiple accept="image/png,image/jpeg,image/webp,image/avif"></label><p class="control-note">اختر المجلد بعد فك ZIP. تُستخدم أسماء مجلدات المدارس والصور للمطابقة، وتُحفظ الصور على GitHub.</p>'+(r.rematchBackup?.visits?.length?'<button class="btn btn-soft btn-small full-width" data-action="undo-drive-images">استرجاع صور ما قبل المطابقة</button>':'')+'<div class="admin-message" id="auto-distribute-status">'+(autoBusy?'يتم الآن تحليل النص ومطابقة الصور…':'اللصق يحفظ مسودة محلية فقط. التنفيذ والحفظ المشترك لا يحدثان إلا بعد الضغط على الزر.')+'</div>'+runNote+'</section><section class="control-group"><h3>قواعد المطابقة</h3><p class="control-note">يفضّل تسمية الصورة بهذا الشكل: <b dir="ltr">2026-05-03_اسم المدرسة_اسم المصنع_01.jpg</b>. إذا تعذرت مطابقة صورة، يضعها النظام في عدد الصور غير المطابقة بدل اختراع زيارة أو صورة.</p><div class="admin-message">مجلد Drive يجب أن يكون متاحًا لأي شخص لديه الرابط. مفاتيح الربط محفوظة في هذا المتصفح، والصور تُنسخ إلى GitHub وتظهر دون انتظار نشر الموقع.</div></section>'}
function mediaControls(r){return '<section class="control-group"><h3>الصور المرتبطة حاليًا</h3><div class="source-summary"><div><b>'+fmt(r.visits.reduce((n,v)=>n+v.images.length,0))+'</b><span>روابط صور في التقرير</span></div><div><b>'+fmt(r.visits.length)+'</b><span>زيارات مرتبطة</span></div></div><p class="control-note" style="margin-top:12px">لإنشاء الكروت وتوزيع الصور تلقائيًا افتح تبويب «التوزيع». هنا تراجع الصور الحالية أو تعدّل رابط صورة داخل تبويب الزيارات.</p><button class="btn btn-dark btn-small full-width" data-action="panel" data-panel="distribution">'+ico('spark')+'فتح التوزيع التلقائي</button></section>'}
function printSelect(label,key,items,p){return '<label class="field"><span>'+label+'</span><select data-print-setting="'+key+'" aria-label="'+label+'">'+items.map(([value,name])=>'<option value="'+value+'" '+(p[key]===value?'selected':'')+'>'+name+'</option>').join('')+'</select></label>'}
function printToggle(label,key,p){return '<label class="switch-row"><span>'+label+'</span><input type="checkbox" data-print-setting="'+key+'" '+(p[key]?'checked':'')+'></label>'}
function printRange(label,key,min,max,unit,p){return '<label class="field"><span>'+label+'<output id="out-print-'+key+'">'+p[key]+unit+'</output></span><input type="range" min="'+min+'" max="'+max+'" value="'+p[key]+'" data-print-setting="'+key+'" data-unit="'+unit+'" aria-label="'+label+'"></label>'}
function printCoverBackgroundControl(p){const preview=p.coverBackground?'<div class="cover-upload-preview" style="background-image:url(&quot;'+esc(p.coverBackground)+'&quot;)" aria-label="معاينة خلفية الغلاف"></div>':'';return '<div class="cover-upload-control"><span class="control-note">خلفية غلاف ثابتة لهذه المنطقة</span>'+preview+'<label class="upload">'+ico('upload')+(p.coverBackground?'استبدال الخلفية':'رفع خلفية الغلاف')+'<input id="print-cover-upload" type="file" accept="image/png,image/jpeg,image/webp,image/avif"></label>'+(p.coverBackground?'<button class="btn btn-soft btn-small full-width" style="margin-top:8px" data-action="remove-cover-background">حذف خلفية الغلاف</button>':'')+'</div>'}
function printPageBackgroundControl(p){return '<section class="control-group"><h3>خلفية الصفحات الداخلية · '+esc(area().name)+'</h3><p class="control-note">تظهر الخلفية نفسها في معاينة A4 والطباعة، على صفحات الزيارات والإحصاءات.</p>'+(p.pageBackground?'<div class="cover-upload-preview" style="background-image:url(&quot;'+esc(p.pageBackground)+'&quot;)"></div>':'')+'<label class="upload">'+ico('upload')+'رفع خلفية الصفحات الداخلية<input id="print-page-upload" type="file" accept="image/png,image/jpeg,image/webp,image/avif"></label>'+(p.pageBackground?'<button class="btn btn-soft btn-small full-width" data-action="remove-page-background">حذف خلفية الصفحات الداخلية</button>':'')+'</section>'}
function printControls(){const p=printSettings(),r=currentReport();return '<section class="control-group"><h3>بناء صفحات التقرير</h3>'+field('اسم الأسبوع / التقرير',reportPeriod(r||{}).week,'data-header="weekTitle" placeholder="الأسبوع السابع" maxlength="120"')+'<label class="field"><span>عدد الزيارات في صفحة A4 · الحد الأقصى 4</span><select id="print-per-page">'+[2,3,4].map(n=>'<option value="'+n+'" '+(p.perPage===n?'selected':'')+'>'+n+' زيارات</option>').join('')+'</select></label><p class="control-note">كل إعدادات هذا التبويب تخص منطقة '+esc(area().name)+' بشكل مستقل، وتنعكس على معاينة A4 نفسها. لا يسمح النظام بأكثر من 4 زيارات في الصفحة.</p><button class="btn btn-dark btn-small full-width" data-action="print-preview">'+ico('file')+'معاينة A4</button></section><section class="control-group"><h3>رأس صفحات التقرير</h3>'+printToggle('إظهار الرأس في الصفحات الداخلية','headerVisible',p)+printToggle('إظهار تاريخ الفترة','headerDateVisible',p)+printSelect('لون شريط الشعارات','headerStyle',[['color','ملون على ورق أبيض'],['white','أبيض لخلفية ملونة']],p)+printSelect('محاذاة الرأس','headerAlign',[['right','يمين'],['center','وسط'],['left','يسار']],p)+printRange('حجم شريط الشعارات','headerScale',70,140,'%',p)+field('عنوان مخصص تحت الشعار',p.headerTitle,'data-print-setting="headerTitle"')+'<p class="control-note">اترك العنوان فارغًا ليظهر عنوان الأسبوع والمنطقة تلقائيًا.</p></section><section class="control-group"><h3>فوتر التقرير</h3><p class="control-note">هذه قائمة شركاء المنطقة الثابتة لكل الأسابيع. تظهر في فوتر الويب والصفحات الداخلية؛ يمكنك رفع الشركاء أو حذفهم من القائمة أدناه.</p>'+printToggle('إظهار الفوتر في الصفحات الداخلية','footerVisible',p)+printToggle('إظهار شعارات شركاء المنطقة','footerPartnersVisible',p)+'<p class="control-note">شعارات شركاء النجاح تتوسط الفوتر في جميع المناطق والتقارير.</p>'+printRange('حجم شعارات الشركاء','footerPartnerSize',70,150,'%',p)+field('عنوان اختياري بجانب الشعارات',p.footerLabel,'data-print-setting="footerLabel"')+field('سطر اختياري في الفوتر',p.footerText,'data-print-setting="footerText"')+printToggle('إظهار ترقيم الصفحات','showPageNumbers',p)+'</section><section class="control-group"><h3>غلاف المنطقة</h3>'+printToggle('إظهار شريط الشعارات الأبيض أعلى الغلاف','coverHeaderVisible',p)+field('سطر اختياري أسفل الغلاف',p.coverFooterText,'data-print-setting="coverFooterText"')+printCoverBackgroundControl(p)+printRange('موضع معلومات الأسبوع تحت الخط','coverTextTop',10,94,'%',p)+'</section>'+printPageBackgroundControl(p)+partnerControls()+'<section class="control-group"><h3>حفظ إعدادات '+esc(area().name)+'</h3><p class="control-note">التعديل يُحفظ تلقائيًا في هذا المتصفح، وزر الحفظ يؤكد النسخة بعد أن تنهي ضبطها.</p><button class="btn btn-dark btn-small full-width" data-action="save-print-settings">'+ico('check')+'حفظ إعدادات الطباعة</button><button class="btn btn-soft btn-small full-width" style="margin-top:8px" data-action="reset-print-region">استعادة نمط الطباعة للمنطقة</button></section><section class="control-group"><h3>ملف الإخراج المطلوب</h3>'+[['screen','للعرض والمشاركة','ضغط أكبر للصور'],['balanced','متوازن','توازن الجودة والحجم'],['print','للطباعة','تفاصيل أعلى للصور']].map(([key,title,sub])=>'<label class="quality-row"><input type="radio" name="pdf-quality" value="'+key+'" '+(saved.print.quality===key?'checked':'')+'><span><b>'+title+'</b><small>'+sub+'</small></span></label>').join('')+'<div class="admin-message">التقارير الناتجة تحفظ على الخادم. استدعاء Drive والتحليل اللغوي المتقدم يحتاجان مفاتيح خدمة محفوظة على الخادم.</div></section>'}
function admin(){let r=currentReport();if(!r){const draft={id:'draft-'+state.region,region:state.region,header:{weekTitle:'',dateRange:''},stats:emptyReportStats(),visits:[]};return '<main class="shell page"><div class="admin-intro"><h1>إدارة '+area().name+'</h1><div class="local-status">أدخل النص ثم افتح تبويب التوزيع واضغط الزر عند الجاهزية</div></div><div class="admin-layout"><aside class="admin-panel"><div class="admin-context"><strong>المنطقة</strong><select data-select="region">'+regionOptions()+'</select></div><nav class="admin-tabs" aria-label="أقسام التحكم">'+[['distribution','التوزيع','spark'],['general','عام','settings'],['design','التصميم','palette'],['factories','المصانع','factory'],['media','الصور','photo'],['print','الطباعة','file']].map(([key,label,icon])=>'<button data-action="panel" data-panel="'+key+'" class="'+(state.panel===key?'active':'')+'">'+ico(icon)+label+'</button>').join('')+'</nav><div class="controls">'+(state.panel==='distribution'?distributionControls(draft):state.panel==='media'?mediaControls(draft):state.panel==='factories'?factoryControls():state.panel==='print'?printControls():state.panel==='design'?designControls():distributionControls(draft))+newReportControls()+'</div></aside><section class="admin-preview"><div class="empty"><h2>لا يوجد تقرير منشور لهذه المنطقة بعد</h2><p>الصق التقرير ورابط الصور في تبويب «التوزيع»، ثم اضغط «تحليل التقرير وإنشاء الكروت»؛ سيُنشأ التقرير هنا تلقائيًا.</p></div>'+factoryFooter(state.region)+'</section></div></main>';
}
 const panels={distribution:()=>distributionControls(r),general:()=>generalControls(r),design:designControls,visits:()=>visitControls(r),factories:factoryControls,media:()=>mediaControls(r),print:printControls};
 const selected=selectedVisit(r), list=visits(r), sample=list;
 return '<main class="shell page"><div class="admin-intro"><div><span class="eyebrow">مساحة الإدارة</span><h1>كل التفاصيل، في مكان واحد.</h1><p>التوزيع، الهوية، الزيارات، المصانع، الصور وإخراج التقرير.</p></div><span class="local-status"><span class="dot"></span>اضغط حفظ التقرير بعد التعديلات ليظهر المحتوى للزوار</span></div><div class="admin-layout"><aside class="admin-panel"><div class="admin-context"><strong>إعدادات التقرير</strong><select data-select="region" aria-label="منطقة الإدارة">'+regionOptions()+'</select><select data-select="report" aria-label="تقرير الإدارة">'+reportOptions()+'</select></div><nav class="admin-tabs" aria-label="أقسام التحكم">'+[['distribution','التوزيع','spark'],['general','عام','settings'],['design','التصميم','palette'],['visits','الزيارات','school'],['factories','المصانع','factory'],['media','الصور','photo'],['print','الطباعة','file']].map(([key,label,icon])=>'<button data-action="panel" data-panel="'+key+'" class="'+(state.panel===key?'active':'')+'">'+ico(icon)+label+'</button>').join('')+'</nav><div class="controls">'+(panels[state.panel]||panels.design)()+'</div></aside><section class="admin-preview"><div class="preview-toolbar"><div><h2>معاينة '+esc(area().name)+' · '+fmt(list.length)+' زيارة</h2><small>تظهر هنا جميع الكروت الناتجة من التوزيع</small></div><div class="preview-toolbar-actions"><button class="btn btn-dark btn-small" data-action="save-report">'+ico('check')+'حفظ التقرير للزوار</button><button class="btn btn-glass btn-small" data-action="viewer">'+ico('eye')+'فتح عرض المشاهد</button></div></div><div class="preview-surface">'+banner(r)+'<div class="visits">'+sample.map((v,i)=>visitCard(v,i)).join('')+'</div><p class="preview-count">التقرير يحتوي على '+fmt(list.length)+' زيارة كاملة، ويمكن مراجعتها أو تعديلها من تبويب الزيارات.</p>'+categories(r)+factoryFooter(state.region)+'</div></section></div></main>'}
function printCover(r,total,p=printSettings()){const h=reportPeriod(r),region=area(),bg=cleanURL(p.coverBackground),partners='',note=String(p.coverFooterText||'').trim();return '<section class="print-page print-cover print-cover--'+region.id+(bg?' uploaded-cover':'')+'"><div class="print-cover-inner"'+(bg?' style="--cover-background-image:url(&quot;'+esc(bg)+'&quot;);--cover-text-top:'+p.coverTextTop+'%"':'')+'>'+(!bg&&p.coverHeaderVisible?'<div class="print-cover-top">'+identityStrip('white','print-cover-identity')+'</div>':'')+'<div class="print-cover-main">'+(!bg?'<span>التقرير الأسبوعي</span><h1>'+esc(region.name)+'</h1>':'')+'<strong>'+esc(h.week)+'</strong>'+periodDates(h,'cover-report-dates')+'</div><div class="print-cover-bottom print-cover-bottom--'+p.footerAlign+'" style="--print-partner-scale:'+(p.footerPartnerSize/100)+'">'+partners+(note?'<small>'+esc(note)+'</small>':'')+(p.showPageNumbers?'<span>1 / '+total+'</span>':'')+'</div></div></section>'}
function printSummaryPage(r,pheader,pfooter,total){const awards=awardCategories(r);const media=[['عدد التغريدات',r.stats.tweets,'link'],['عدد المنشورات',r.stats.posts,'file'],['اللقاءات التلفزيونية',r.stats.tvInterviews,'photo'],['عدد مقاطع الفيديو',r.stats.videos,'play']];const mark=identityURL('futureIndustrialists')||cleanURL(seed.logo);return '<section class="print-page print-summary-page"'+interiorBackground()+'>'+pheader+'<section class="print-impact"><div class="print-impact-row"><img src="'+esc(mark)+'" alt=""><div><b>'+fmt(r.stats.totalBeneficiaries)+'</b><span>إجمالي عدد المستفيدين من المبادرة حتى صدور هذا التقرير</span></div></div><div class="print-impact-row"><span class="print-impact-icon">'+ico('file')+'</span><div><b>'+fmt(r.stats.totalRegistered)+'</b><span>إجمالي المسجلين في الجائزة حتى صدور هذا التقرير</span></div></div></section><section class="print-awards"><h2>فئات الجائزة</h2><div class="print-award-grid">'+awards.map(x=>'<div class="print-award">'+categoryIcon(x.key,'print-award-icon')+'<span>'+x.name+'</span><b>'+fmt(x.value)+'</b></div>').join('')+'</div></section><section class="print-media-grid">'+media.map(([label,value,icon])=>'<div>'+ico(icon)+'<span>'+label+'</span><b>'+fmt(value)+'</b></div>').join('')+'</section>'+pfooter(total)+'</section>'}
function printHeader(r,p){if(!p.headerVisible)return '';const h=reportPeriod(r),title=String(p.headerTitle||'').trim()||('التقرير الأسبوعي ('+area().name+') · '+h.week),future=identityURL('futureIndustrialists')||cleanURL(seed.logo);return '<div class="print-header print-header--'+p.headerAlign+' print-header--'+p.headerStyle+'" style="--print-header-scale:'+(p.headerScale/100)+'"><div class="print-header-brands"><img class="print-header-future" src="'+esc(future)+'" alt="صناعيو المستقبل">'+identityStrip(p.headerStyle,'print-page-identity')+'</div><small>'+esc(title)+'</small>'+(p.headerDateVisible?periodDates(h,'print-report-dates'):'')+'</div>'}
function printFooter(n,total,p){if(!p.footerVisible)return '';const note=String(p.footerText||'').trim(),partners=p.footerPartnersVisible?partnerStrip(state.region,'print-footer-partners',p.footerLabel||'شركاء النجاح'):'';return '<div class="print-footer print-footer--'+p.footerAlign+'" style="--print-partner-scale:'+(p.footerPartnerSize/100)+'"><div>'+partners+(note?'<span class="print-footer-note">'+esc(note)+'</span>':'')+'</div>'+(p.showPageNumbers?'<span>'+n+' / '+total+'</span>':'')+'</div>'}
function printView(){const r=currentReport();if(!r)return report();const list=visits(r), chunks=[],p=printSettings(),perPage=Math.max(1,Math.min(4,Number(p.perPage)||4));for(let i=0;i<list.length;i+=perPage)chunks.push(list.slice(i,i+perPage));const total=chunks.length+2;
 const pheader=printHeader(r,p),pfooter=n=>printFooter(n,total,p);
 return '<main class="print-shell page"><div class="print-toolbar"><div><h1>معاينة التقرير</h1><p>معاينة A4 · '+total+' صفحات · '+perPage+' زيارات كحد أقصى في الصفحة</p></div><div><button class="btn btn-glass" data-action="back-print">رجوع</button><button class="btn btn-white" data-action="download-pdf">'+ico('download')+(isIOSDevice()?'تجهيز PDF للحفظ':'تنزيل PDF')+'</button><button class="btn btn-glass" data-action="print">'+ico('file')+'طباعة</button><span id="pdf-download-result"></span></div></div><div class="print-pages">'+printCover(r,total,p)+chunks.map((chunk,i)=>'<section class="print-page print-visits-page"'+interiorBackground(p)+'>'+pheader+'<div class="print-visit-list" style="grid-template-rows:repeat('+perPage+',minmax(0,1fr))">'+chunk.map((v,j)=>visitCard(v,i*perPage+j,true)).join('')+'</div>'+pfooter(i+2)+'</section>').join('')+printSummaryPage(r,pheader,pfooter,total)+'</div></main>'}
function fitPaperPreview(){const box=document.querySelector('.live-a4-preview'),paper=box?.querySelector('.print-shell');if(!paper)return;const width=Math.max(1,box.clientWidth-24);paper.style.zoom=Math.min(1,width/(210*96/25.4));box.querySelectorAll('img').forEach(img=>img.loading='eager')}
window.addEventListener('resize',fitPaperPreview);
function previewMode(){return state.previewDevice||(state.panel==='print'?'a4':'web')}
function previewDeviceControls(){const mode=previewMode();return '<div class="preview-device-controls" role="group" aria-label="مقاس المعاينة">'+[['web','ويب'],['iphone','آيفون'],['android','أندرويد'],['a4','A4']].map(([key,label])=>'<button type="button" data-action="preview-device" data-device="'+key+'" aria-pressed="'+(mode===key)+'" class="'+(mode===key?'active':'')+'">'+label+'</button>').join('')+'</div>'}
function previewToolbar(title){return '<div class="preview-toolbar"><div><h2>'+esc(title)+'</h2>'+previewDeviceControls()+'</div><button class="btn btn-dark btn-small" data-action="save-report">حفظ التقرير للزوار</button></div>'}
function devicePreviewDocument(){const originalView=state.view;let content;try{renderingDevicePreview=true;state.view='report';content=header()+report()+footer()}finally{state.view=originalView;renderingDevicePreview=false}const root=document.documentElement,attrs=Object.entries(root.dataset).filter(([key])=>key!=='view').map(([key,value])=>'data-'+key.replace(/[A-Z]/g,c=>'-'+c.toLowerCase())+'="'+esc(value)+'"').join(' '),css=new URL('styles.css?v=20261015-controls-20',location.href).href;return '<!doctype html><html lang="ar" dir="rtl" data-view="report" '+attrs+' style="'+esc(root.getAttribute('style')||'')+'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><base href="'+esc(new URL('./',location.href).href)+'"><link rel="stylesheet" href="'+esc(css)+'"><style>html{scrollbar-width:none}html::-webkit-scrollbar{display:none}body{min-width:0}.reveal,.reveal[data-reveal="waiting"]{opacity:1!important;transform:none!important}.photo img{opacity:1!important}.ambient,.grid-haze,.grain{animation:none!important}</style></head><body><div class="ambient"></div><div class="grid-haze"></div>'+content+'</body></html>'}
function fitDevicePreview(){const frame=document.querySelector('.device-preview-frame'),stage=document.querySelector('.device-preview-stage');if(!frame||!stage)return;const w=Number(frame.dataset.width)+16,h=Number(frame.dataset.height)+16,available=stage.parentElement.clientWidth-24,scale=Math.min(1,Math.max(.2,available/w),Math.max(360,window.innerHeight-240)/h);stage.style.width=w*scale+'px';stage.style.height=h*scale+'px';frame.style.transform='scale('+scale+')'}
window.addEventListener('resize',fitDevicePreview);
function refreshAdminPreview(){
 if(state.view!=='admin')return;const preview=document.querySelector('.admin-preview');if(!preview)return;const mode=previewMode(),r=currentReport();if(!r)return;
 if(mode==='iphone'||mode==='android'){
  let scroll=0;try{scroll=preview.querySelector('iframe')?.contentDocument?.scrollingElement?.scrollTop||0}catch{}
  const w=mode==='iphone'?390:412,h=mode==='iphone'?844:915,name=mode==='iphone'?'آيفون':'أندرويد';
  preview.innerHTML=previewToolbar('معاينة '+name+' · '+area().name)+'<div class="device-preview"><p class="device-preview-note">مقاس الشاشة '+w+' × '+h+' · مرّر داخل الشاشة لمشاهدة التقرير</p><div class="device-preview-stage"><div class="device-preview-frame" data-width="'+w+'" data-height="'+h+'" style="width:'+w+'px;height:'+h+'px"><iframe title="معاينة '+name+'" sandbox="allow-same-origin" style="width:'+w+'px;height:'+h+'px"></iframe></div></div></div>';
  const iframe=preview.querySelector('iframe');iframe.addEventListener('load',()=>{try{const doc=iframe.contentDocument;doc.scrollingElement.scrollTop=scroll;doc.addEventListener('click',event=>{if(!event.target.closest?.('[data-action="print-preview"]'))return;event.preventDefault();state.beforePrint='admin';state.view='print';render(true)})}catch{}},{once:true});iframe.srcdoc=devicePreviewDocument();fitDevicePreview();return;
 }
 if(mode==='a4'){const scroll=preview.querySelector('.live-a4-preview')?.scrollTop||0;preview.innerHTML=previewToolbar('معاينة A4 مباشرة')+'<div class="live-a4-preview">'+printView()+'</div>';preview.querySelector('.live-a4-preview').scrollTop=scroll;fitPaperPreview();return}
 let toolbar=preview.querySelector('.preview-toolbar');if(toolbar&&!toolbar.querySelector('.preview-device-controls'))toolbar.insertAdjacentHTML('beforeend',previewDeviceControls());
 let surface=preview.querySelector('.preview-surface');if(!surface){preview.innerHTML=previewToolbar('معاينة الويب · '+area().name)+'<div class="preview-surface"></div>';surface=preview.querySelector('.preview-surface')}
 if(r)surface.innerHTML=banner(r)+'<div class="visits">'+visits(r).map((v,i)=>visitCard(v,i)).join('')+'</div>'+categories(r)+factoryFooter(state.region);
}

let revealObserver;
function enhance(){if(revealObserver)revealObserver.disconnect();if(!window.IntersectionObserver||!saved.theme.motion||reducedMotion.matches)return;revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.dataset.reveal='visible';revealObserver.unobserve(e.target)}}),{threshold:.06});document.querySelectorAll('.reveal').forEach(el=>{el.dataset.reveal='waiting';revealObserver.observe(el)})}
function render(scroll=false){document.documentElement.dataset.view=state.view;applyTheme();const controlScroll=state.resetControls?0:(document.querySelector('.controls')?.scrollTop||0);state.resetControls=false;document.getElementById('app').innerHTML=header()+(state.view==='home'?home():state.view==='admin'?admin():state.view==='print'?printView():report())+footer();if(state.view==='admin')refreshAdminPreview();const controls=document.querySelector('.controls');if(controls)controls.scrollTop=controlScroll;if(state.view==='print')document.querySelectorAll('.print-page img').forEach(img=>img.loading='eager');document.querySelectorAll('[data-select]').forEach(el=>el.disabled=autoBusy);enhance();if(state.view==='admin'&&state.panel==='general'&&!aiStatus.loaded&&!aiStatus.loading)loadAIStatus();if(scroll)window.scrollTo({top:0,behavior:'instant'})}
function chooseRegion(id){state.region=regions.some(r=>r.id===id)?id:'makkah';state.reportId=regionReports().at(-1)?.id||'';state.search='';state.gender='all';state.selectedVisit=''}
function refreshResults(){const r=currentReport(),el=document.getElementById('visit-results');if(!r||!el)return;el.innerHTML=visitsMarkup(r);document.getElementById('result-count').textContent=fmt(filteredVisits(r).length)+' زيارة';enhance()}
function openLightbox(key,index){const r=currentReport(),v=r&&visits(r).find(v=>v._key===key);if(!v)return;state.lightbox=v;state.lightboxIndex=index;drawLightbox();const dialog=document.getElementById('lightbox');if(!dialog.open)dialog.showModal()}
function drawLightbox(){const v=state.lightbox;if(!v)return;const i=state.lightboxIndex,url=v.images[i];document.getElementById('lightbox').innerHTML='<div class="lightbox-top"><div><h2>'+esc(v.schoolName)+'</h2><p>'+esc(v.factory)+' · '+esc(v.date)+'</p></div><button class="icon-btn" data-action="close-lightbox" aria-label="إغلاق عارض الصور">'+ico('close')+'</button></div><div class="lightbox-body"><span class="lightbox-error">'+(url?'جارٍ تحميل الصورة…':'لا توجد صورة مرفقة')+'</span>'+(url?'<img data-lightbox-image src="'+esc(url)+'" alt="صورة الزيارة">':'')+'</div><div class="lightbox-bottom"><button class="icon-btn" data-action="previous-image" aria-label="الصورة السابقة">'+ico('back')+'</button><span>'+(i+1)+' / 4</span><button class="icon-btn" data-action="next-image" aria-label="الصورة التالية">'+ico('arrow')+'</button></div>'}
function nextImage(step){state.lightboxIndex=(state.lightboxIndex+step+4)%4;drawLightbox()}
