function updateMediaStatus(){const status=document.getElementById('media-load-status');if(!status)return;const images=[...document.querySelectorAll('.admin-preview [data-photo]')];const loaded=images.filter(img=>img.complete&&img.naturalWidth>0).length,failed=images.filter(img=>img.dataset.failed==='true').length;status.textContent=images.length?'تحميل صور الكروت: '+loaded+' / '+images.length+(failed?' · '+failed+' صور تعذر تحميلها':''):''}
const logoFitJobs=new Map();
function fitLogoImage(img){if(img.dataset.logoFitted)return;img.dataset.logoFitted='true';const src=img.currentSrc||img.src;if(!src)return;let task=logoFitJobs.get(src);if(!task){task=(async()=>{try{const source=new Image();source.crossOrigin='anonymous';source.src=src;await source.decode();const scale=Math.min(1,640/Math.max(source.naturalWidth,source.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(source.naturalWidth*scale));canvas.height=Math.max(1,Math.round(source.naturalHeight*scale));const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(source,0,0,canvas.width,canvas.height);const data=context.getImageData(0,0,canvas.width,canvas.height).data;let left=canvas.width,top=canvas.height,right=-1,bottom=-1;for(let y=0;y<canvas.height;y++)for(let x=0;x<canvas.width;x++){const n=(y*canvas.width+x)*4;if(data[n+3]>32&&Math.min(data[n],data[n+1],data[n+2])<235){left=Math.min(left,x);top=Math.min(top,y);right=Math.max(right,x);bottom=Math.max(bottom,y)}}if(right<left||bottom<top)return src;const pad=Math.ceil(Math.max(right-left,bottom-top)*.025);left=Math.max(0,left-pad);top=Math.max(0,top-pad);right=Math.min(canvas.width-1,right+pad);bottom=Math.min(canvas.height-1,bottom+pad);if((right-left+1)>canvas.width*.95&&(bottom-top+1)>canvas.height*.95)return src;const result=document.createElement('canvas');result.width=right-left+1;result.height=bottom-top+1;result.getContext('2d').drawImage(canvas,left,top,result.width,result.height,0,0,result.width,result.height);return result.toDataURL('image/png')}catch{return src}})();logoFitJobs.set(src,task)}task.then(url=>{if(img.isConnected&&url!==src)img.src=url})}
document.addEventListener('load',e=>{const img=e.target;if(img.tagName!=='IMG')return;delete img.dataset.failed;img.classList.remove('image-failed');if(img.hasAttribute('data-photo'))img.classList.add('loaded');if(img.hasAttribute('data-logo')){fitLogoImage(img);img.style.opacity='1';const fallback=img.parentElement.querySelector('.logo-fallback');if(fallback)fallback.style.visibility='hidden'}if(img.hasAttribute('data-lightbox-image')){const status=img.parentElement.querySelector('.lightbox-error');if(status)status.textContent=''}updateMediaStatus()},true);
document.addEventListener('error',e=>{const img=e.target;if(img.tagName!=='IMG')return;img.dataset.failed='true';img.classList.add('image-failed');if(img.hasAttribute('data-photo')){const status=img.parentElement.querySelector('.image-status');if(status)status.textContent='تعذر تحميل الصورة من المصدر'}if(img.hasAttribute('data-lightbox-image'))img.parentElement.querySelector('.lightbox-error').textContent='تعذر تحميل الصورة من مصدرها.';updateMediaStatus()},true);
document.getElementById('lightbox').addEventListener('click',e=>{if(e.target===e.currentTarget)closeLightbox()});
document.getElementById('lightbox').addEventListener('close',()=>state.lightbox=null);
document.addEventListener('keydown',e=>{if(!document.getElementById('lightbox').open)return;if(e.key==='ArrowLeft'){e.preventDefault();nextImage(1)}if(e.key==='ArrowRight'){e.preventDefault();nextImage(-1)}});
