function exportSettings(){const blob=new Blob([JSON.stringify({schemaVersion:2,exportedAt:new Date().toISOString(),...saved},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='future-industrialists-settings.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('تم تصدير إعدادات التصميم والشعارات والتعديلات.')}
function reportFileName(r){const region=regions.find(x=>x.id===r?.region)?.name||area().name;return ('صناعيو المستقبل - '+reportPeriod(r||{}).week+' - '+region).replace(/[\\/:*?"<>|\u0000-\u001f]/g,' ').replace(/\s+/g,' ').trim()+'.pdf'}
let pdfExportBusy=false,pdfDownloadURL='',pdfDownloadBlob=null,pdfDownloadName='';
function isIOSDevice(){return /iPad|iPhone|iPod/.test(navigator.userAgent)||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1}
async function shareReportPDF(){if(!pdfDownloadBlob)return;const file=new File([pdfDownloadBlob],pdfDownloadName,{type:'application/pdf'});try{if(navigator.share&&navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:pdfDownloadName.replace(/\.pdf$/,'')});}else{const a=document.createElement('a');a.href=pdfDownloadURL;a.download=pdfDownloadName;a.target='_blank';a.rel='noopener';document.body.append(a);a.click();a.remove();toast('من معاينة PDF اضغط مشاركة ثم حفظ في الملفات.');}}catch(error){if(error.name!=='AbortError')toast('تعذر فتح قائمة الحفظ: '+error.message)}}
async function downloadReportPDF(){
 if(pdfExportBusy)return;pdfExportBusy=true;
 const buttons=[...document.querySelectorAll('[data-action="download-pdf"],[data-action="print"]')];buttons.forEach(b=>b.disabled=true);
 try{await loadPDFExporter();await document.fonts.ready;await Promise.allSettled([...logoFitJobs.values()]);await window.FI_PDF.download({filename:reportFileName(currentReport()),onProgress:(n,total)=>toast('جارٍ تجهيز PDF · الصفحة '+n+' من '+total),onReady:blob=>{
  if(pdfDownloadURL)URL.revokeObjectURL(pdfDownloadURL);pdfDownloadURL=URL.createObjectURL(blob);pdfDownloadBlob=blob;pdfDownloadName=reportFileName(currentReport());
  const result=document.getElementById('pdf-download-result');if(result){result.replaceChildren();const link=document.createElement('a');link.className='btn btn-white';link.href=pdfDownloadURL;link.download=reportFileName(currentReport());link.textContent=isIOSDevice()?'فتح ملف PDF':'حفظ ملف PDF';if(isIOSDevice()){const share=document.createElement('button');share.type='button';share.className='btn btn-white';share.dataset.action='share-pdf';share.textContent='حفظ / مشاركة PDF';const note=document.createElement('small');note.textContent='اختر «حفظ في الملفات» من القائمة.';result.append(share,note)}result.append(link)}
  if(!isIOSDevice()){const a=document.createElement('a');a.href=pdfDownloadURL;a.download=pdfDownloadName;document.body.append(a);a.click();a.remove();}
 }});toast(isIOSDevice()?'الملف جاهز. اضغط «حفظ / مشاركة PDF» ثم «حفظ في الملفات».':'تم تجهيز ملف PDF وتنزيله.');}
 catch(error){toast('تعذر تجهيز PDF: '+error.message)}finally{pdfExportBusy=false;buttons.forEach(b=>b.disabled=false)}
}
let pdfExporterPromise;
function loadPDFExporter(){if(window.FI_PDF)return Promise.resolve();if(!pdfExporterPromise)pdfExporterPromise=(async()=>{for(const src of ['vendor/html2canvas.min.js','vendor/jspdf.umd.min.js','pdf-export.js'])await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=new URL(src+'?v=20261015-controls-20',location.href).href;script.onload=resolve;script.onerror=()=>reject(new Error('تعذر تحميل أدوات PDF؛ أعد المحاولة.'));document.body.append(script)})})().catch(error=>{pdfExporterPromise=null;throw error});return pdfExporterPromise}
let preparingPrint=false;
async function preparePrint(){
 if(preparingPrint)return;preparingPrint=true;const button=document.querySelector('[data-action="print"]');if(button)button.disabled=true;
 try{
  toast('جارٍ تحميل الصور والشعارات للطباعة…');const imgs=[...document.querySelectorAll('.print-page img')];imgs.forEach(img=>img.loading='eager');
  const backgrounds=[printSettings().coverBackground,printSettings().pageBackground].filter(Boolean).map(url=>{const image=new Image();image.src=url;return image});const printImages=[...imgs,...backgrounds];
  let timeout;await Promise.race([Promise.allSettled([document.fonts?.ready,...logoFitJobs.values(),...printImages.map(img=>img.decode?.())]),new Promise(resolve=>timeout=setTimeout(resolve,30000))]);clearTimeout(timeout);
  const failed=printImages.filter(img=>!img.complete||!img.naturalWidth);if(failed.length)toast('بعض الصور غير متاحة؛ ستظهر أماكنها فارغة في الطباعة.');
  document.querySelectorAll('.print-visits-page').forEach(page=>{const list=page.querySelector('.print-visit-list');if(list&&list.scrollHeight>list.clientHeight+2)page.classList.add('print-compact')});
  document.title=reportFileName(currentReport()).replace(/\.pdf$/,'');
  window.print();
 }finally{preparingPrint=false;if(button)button.disabled=false}
}
