function createReportFromAdmin(){const week=document.getElementById('new-report-week')?.value.trim()||'',date=document.getElementById('new-report-date')?.value.trim()||'';if(!week||!date){toast('اكتب عنوان الأسبوع والفترة الزمنية أولًا.');return}const id='custom-'+state.region+'-'+Date.now();saved.reports.push({id,region:state.region,header:{weekTitle:week,dateRange:date},stats:emptyReportStats(),visits:[]});state.reportId=id;state.selectedVisit='';state.panel='general';persist('تم إنشاء تقرير '+week+' لمنطقة '+area().name+'.');render(true)}
async function moveCurrentReport(targetRegion){const report=currentReport();if(!report){toast('لا يوجد تقرير لنقله.');return}let target=editableReport(report.id);if(!target){target=JSON.parse(JSON.stringify(report));saved.reports.push(target)}const next=regions.some(region=>region.id===targetRegion)?targetRegion:'';if(!next||next===target.region){toast('اختر منطقة مختلفة أولًا.');return}if(!confirm('سيتم نقل التقرير وجميع زياراته إلى '+regionById(next).name+'. هل تريد المتابعة؟'))return;const previous=target.region;target.region=next;state.region=next;state.reportId=target.id;state.selectedVisit='';saved.sources[next]=saved.sources[next]||saved.sources[previous]||'';persist('تم نقل التقرير إلى '+regionById(next).name+'.');const synced=await syncRemoteReport(target);toast(synced?'تم نقل التقرير وحفظه على المنصة.':'تم نقل التقرير محليًا؛ تعذر تأكيد الحفظ على المنصة.');render(true)}
async function deleteCurrentReport(){const report=currentReport();if(!report){toast('لا يوجد تقرير لحذفه.');return}if(!confirm('سيتم حذف هذا التقرير وجميع زياراته نهائيًا. هل أنت متأكد؟'))return;const id=report.id;saved.deletedReports[id]=new Date().toISOString();saved.reports=saved.reports.filter(item=>item?.id!==id);clearReportOverlays(id);delete saved.intakes[id];delete saved.automation[id];const oldRegion=state.region;state.reportId='';persist('تم إخفاء التقرير فورًا.');await reportSaveQueue.catch(()=>{});const removed=await deleteRemoteReport(id);state.reportId=regionReports().at(-1)?.id||'';toast(removed?'تم حذف التقرير نهائيًا من المنصة.':'تم إخفاؤه على هذا الجهاز؛ تعذر تأكيد الحذف من المنصة.');if(!regionReports().length)state.region=oldRegion;render(true)}
