function automationVisit(item,index){const raw=item&&typeof item==='object'?item:{};const images=Array.isArray(raw.images)?raw.images:[];const participants=Math.max(0,Math.floor(Number(raw.participants)||0));const schoolName=String(raw.schoolName||raw.school||'زيارة مدرسية').trim();const factory=String(raw.factory||raw.factoryName||'مصنع غير محدد').trim();const date=String(raw.date||'').trim();const gender=['boys','girls','unspecified'].includes(raw.gender)?raw.gender:inferGender(schoolName);return {id:String(raw.id||('auto-visit-'+Date.now()+'-'+index)),schoolName,factory,date,participants,gender,factoryLogo:driveImageURL(raw.factoryLogo),images:images.map(driveImageURL).filter(Boolean).slice(0,4),imagePositions:raw.imagePositions||{}}}
