function recoverRegionLogoSettings(){let changed=false;for(const region of regions){const p=regionPresentation(region.id);if(p.recoveredLogoVersion!==1||saved.recoveredLogoVersions?.[region.id]===1)continue;for(const [key,f] of Object.entries(p.factories||{})){const local=saved.factories[key];if(!local?.url&&local?.logoHidden!==true){saved.factories[key]={...local,...f,region:region.id};changed=true}}if(!saved.partners[region.id]?.length&&p.partners?.length){saved.partners[region.id]=p.partners.map(item=>({...item}));saved.partnerRegistryConfigured[region.id]=true;changed=true}saved.recoveredLogoVersions={...saved.recoveredLogoVersions,[region.id]:1};changed=true}return changed}
async function hydrateRemoteReports(){if(typeof fetch!=='function')return;try{const response=await fetch('/api/reports');if(!response.ok)return;const payload=await response.json(),remote=Array.isArray(payload?.reports)?payload.reports:[],deleted=Array.isArray(payload?.deletedReports)?payload.deletedReports.map(String):[];let changed=false;for(const id of deleted){if(!id)continue;if(!saved.deletedReports[id]){saved.deletedReports[id]=new Date().toISOString();changed=true}const before=saved.reports.length;saved.reports=saved.reports.filter(item=>item?.id!==id);if(saved.reports.length!==before){clearReportOverlays(id);changed=true}}for(const report of remote){if(!report||!report.id||!report.region||saved.deletedReports?.[report.id])continue;const index=saved.reports.findIndex(x=>x&&x.id===report.id);if(index<0){saved.reports.push(report);changed=true}else if(JSON.stringify(saved.reports[index])!==JSON.stringify(report)){saved.reports[index]=report;clearReportOverlays(report.id);changed=true}}changed=recoverRegionLogoSettings()||changed;if(changed){persist();if(state.view!=='print')render()}}catch(error){/* Offline use intentionally continues with the last local copy. */}}
