async function importRegionPartners(localFiles){
 if(autoBusy)return;
 const region=state.region,r=currentReport(),link=document.getElementById('partner-source-folder')?.value.trim()||saved.partnerSources[region]||'';
 if(!r){toast('اختر تقريرًا للمنطقة أولًا.');return}
 if(!window.FI_GITHUB.connected()){toast('اربط GitHub أولًا.');return}
 if(!localFiles&&!link){toast('أدخل رابط مجلد الشعارات أولًا.');return}
 autoBusy=true;document.querySelectorAll('[data-select]').forEach(el=>el.disabled=true);
 const button=document.querySelector('[data-action="import-partner-drive"]');if(button)button.disabled=true;
 const status=document.getElementById('partner-import-status');if(status)status.textContent='جارٍ جلب شعارات '+area().name+'…';
 let message='';
 try{
  let incoming;
  if(localFiles){
   const files=Array.from(localFiles).filter(f=>['image/png','image/jpeg','image/webp','image/avif'].includes(f.type));
   if(!files.length||files.length>250)throw Error('اختر مجلدًا يحتوي من 1 إلى 250 صورة شعار.');
   incoming=[];
   for(const file of files){if(status)status.textContent='جارٍ رفع الشعار '+(incoming.length+1)+' من '+files.length+'…';incoming.push({id:'local-partner-'+Date.now()+'-'+incoming.length,name:file.name.replace(/\.[^.]+$/,''),url:await storeReportImage(await logoFromFile(file)),scale:100})}
  }else incoming=await window.FI_DRIVE.importPartners(link);
  const list=partnersFor(region).map(p=>({...p}));
  for(const item of incoming){const index=list.findIndex(p=>norm(canonicalFactory(p.name))===norm(canonicalFactory(item.name))||p.url===item.url);if(index>=0)list[index]={...list[index],url:item.url};else list.push(item)}
  saved.partners[region]=list;saved.partnerRegistryConfigured[region]=true;if(!localFiles)saved.partnerSources[region]=link;
  persist();const ok=await syncRemoteReport(r);
  message=ok?'تم جلب '+incoming.length+' شعارًا وحفظ شركاء '+regionById(region).name+' لكل تقارير المنطقة.':'تم جلب الشعارات محليًا. '+lastSaveError;
 }catch(error){message=error.message||'تعذر استيراد الشعارات. القائمة السابقة لم تتغير.'}
 finally{autoBusy=false;render();const output=document.getElementById('partner-import-status');if(output)output.textContent=message;toast(message)}
}

async function importLocalPhotoFolder(fileList){
 if(autoBusy)return;
 const r=currentReport(),runRegion=state.region;
 if(!r?.visits?.length){toast('أنشئ زيارات التقرير أولًا.');return}
 if(!window.FI_GITHUB.connected()){toast('اربط GitHub أولًا لحفظ الصور.');return}
 const files=Array.from(fileList||[]).filter(f=>['image/png','image/jpeg','image/webp','image/avif'].includes(f.type));
 if(!files.length){toast('المجلد لا يحتوي صور PNG أو JPG أو WebP أو AVIF.');return}
 if(files.length>5000){toast('اختر مجلد الأسبوع فقط؛ الحد الأقصى 5000 صورة.');return}
 const original=visits(r).map(({_key,...v})=>({...v,images:[...(v.images||[])],imagePositions:{...(v.imagePositions||{})}}));
 const candidates=files.map((file,i)=>({id:'local-'+i,name:file.webkitRelativePath||file.name,url:'local-photo:'+i}));
 const nextVisits=original.map(v=>({...v,images:[]}));
 const result=window.FI_MATCH(nextVisits,candidates);
 if(!result.matchedImages){toast('لم تطابق أسماء المجلدات والصور المدارس. الصور الحالية لم تتغير.');return}
 autoBusy=true;document.querySelectorAll('[data-select]').forEach(el=>el.disabled=true);
 const selected=new Set(nextVisits.flatMap(v=>v.images)),urls=new Map();
 try{
  let completed=0;
  for(let i=0;i<files.length;i++){
   const source='local-photo:'+i;if(!selected.has(source))continue;
   setAutomationStatus('جارٍ رفع الصور '+(++completed)+' من '+selected.size+'…');
   urls.set(source,await storeReportImage(await imageFromFile(files[i])));
  }
  nextVisits.forEach((v,i)=>{v.images=v.images.length?v.images.map(url=>urls.get(url)):[...original[i].images];v.imagePositions={...original[i].imagePositions}});
  const next=editableReport(r.id);if(!next)throw Error('التقرير لم يعد متاحًا. الصور الحالية لم تتغير.');
  next.rematchBackup={updatedAt:new Date().toISOString(),visits:original.map(v=>({id:v.id,images:v.images,imagePositions:v.imagePositions}))};
  next.visits=nextVisits;
  for(const visit of nextVisits){const key=vkey(next,visit);if(saved.visits[key])saved.visits[key]={...saved.visits[key],images:visit.images,imagePositions:visit.imagePositions}}
  saved.automation[next.id]={updatedAt:new Date().toISOString(),matchedImages:result.matchedImages,unmatchedImages:result.unmatchedImages||0,warnings:result.warnings||[]};
  persist();const synced=await syncRemoteReport(next);
  state.region=runRegion;state.reportId=r.id;
  toast('تم توزيع '+result.matchedImages+' صورة'+(synced?' وحفظها للزوار':' محليًا؛ '+lastSaveError));
 }catch(error){setAutomationStatus(error.message||'تعذر رفع الصور.');toast(error.message||'تعذر رفع الصور.');}
 finally{autoBusy=false;render()}
}

