  persist();const synced=await syncRemoteReport(next);setAutomationStatus((result.matchedImages||0)+' صورة تمت مطابقتها'+(result.unmatchedImages?' · '+result.unmatchedImages+' تحتاج مراجعة':'')+(result.warnings?.length?' · راجع الملاحظات أدناه':''));toast('تمت إعادة مطابقة الصور'+(synced?' وحفظها للزوار':' وحفظها محليًا'));render(true);
