async function logoFromFile(file){if(!['image/png','image/jpeg','image/webp','image/avif'].includes(file.type))throw new Error('اختر صورة PNG أو JPG أو WebP أو AVIF.');if(file.size>12*1024*1024)throw new Error('اختر شعارًا أصغر من 12 ميجابايت.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const ratio=Math.min(1,640/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(img.naturalHeight*ratio));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/webp',.92)}finally{URL.revokeObjectURL(url)}}
async function imageFromFile(file){if(!['image/png','image/jpeg','image/webp','image/avif'].includes(file.type))throw new Error('اختر خلفية PNG أو JPG أو WebP أو AVIF.');if(file.size>16*1024*1024)throw new Error('اختر خلفية أصغر من 16 ميجابايت.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const ratio=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(img.naturalHeight*ratio));const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/webp',.86)}finally{URL.revokeObjectURL(url)}}
