function savePhotoPosition(key,index,position){const r=currentReport(),v=r&&visits(r).find(item=>item._key===key),url=v?.images[index];if(!url)return;const value={x:Math.max(0,Math.min(100,position.x)),y:Math.max(0,Math.min(100,position.y))};saved.visits[key]={...saved.visits[key],imagePositions:{...v.imagePositions,[url]:value}};persist();document.querySelectorAll('[data-photo-key]').forEach(box=>{if(box.dataset.photoKey===key&&Number(box.dataset.photoIndex)===index){const image=box.querySelector('[data-photo]');if(image)image.style.objectPosition=value.x+'% '+value.y+'%'}});scheduleReportSync('تم حفظ موضع الصورة للزوار.')}
let photoPan=null;
document.addEventListener('pointerdown',e=>{const box=e.target.closest?.('.photo-editable');if(!box||e.target.closest('.photo-tools')||e.button!==0)return;const img=box.querySelector('[data-photo]');if(!img?.naturalWidth)return;const r=currentReport(),v=r&&visits(r).find(item=>item._key===box.dataset.photoKey);if(!v)return;const position=photoPosition(v,v.images[Number(box.dataset.photoIndex)]),rect=box.getBoundingClientRect(),scale=Math.max(rect.width/img.naturalWidth,rect.height/img.naturalHeight);photoPan={box,img,key:v._key,index:Number(box.dataset.photoIndex),pointer:e.pointerId,startX:e.clientX,startY:e.clientY,x:position.x,y:position.y,overflowX:img.naturalWidth*scale-rect.width,overflowY:img.naturalHeight*scale-rect.height,next:position};e.preventDefault();box.setPointerCapture(e.pointerId);box.classList.add('photo-panning')});
