function finishPhotoPan(e){const pan=photoPan;if(!pan||pan.pointer!==e.pointerId)return;photoPan=null;pan.box.classList.remove('photo-panning');if(pan.box.hasPointerCapture(e.pointerId))pan.box.releasePointerCapture(e.pointerId);savePhotoPosition(pan.key,pan.index,pan.next)}
