const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
const networkCanvas=document.getElementById('network'),ctx=networkCanvas.getContext('2d');
let dots=[],width=0,height=0,networkFrame=0,lastTime=0;
function sizeNetwork(){width=window.innerWidth;height=window.innerHeight;const ratio=Math.min(window.devicePixelRatio||1,1.6);networkCanvas.width=width*ratio;networkCanvas.height=height*ratio;ctx.setTransform(ratio,0,0,ratio,0,0);const count=Math.min(86,Math.max(28,Math.round(width*height/18000)));dots=Array.from({length:count},()=>({x:Math.random()*width,y:Math.random()*height,vx:(Math.random()-.5)*.30,vy:(Math.random()-.5)*.30,r:Math.random()*1.45+.8}));drawNetwork(0,false)}
function drawNetwork(time,move=true){ctx.clearRect(0,0,width,height);const dt=lastTime?Math.min((time-lastTime)/16.67,2):1;lastTime=time;for(const p of dots){if(move){p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.x<0||p.x>width)p.vx*=-1;if(p.y<0||p.y>height)p.vy*=-1}ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle='rgba(208,220,255,.54)';ctx.fill()}const distance=window.innerWidth<600?140:195;for(let i=0;i<dots.length;i++)for(let j=i+1;j<dots.length;j++){const d=Math.hypot(dots[i].x-dots[j].x,dots[i].y-dots[j].y);if(d<distance){ctx.beginPath();ctx.moveTo(dots[i].x,dots[i].y);ctx.lineTo(dots[j].x,dots[j].y);ctx.strokeStyle='rgba(198,213,250,'+((1-d/distance)*.26)+')';ctx.lineWidth=.9;ctx.stroke()}}}
function animateNetwork(time){drawNetwork(time,true);networkFrame=requestAnimationFrame(animateNetwork)}
function updateNetwork(){cancelAnimationFrame(networkFrame);networkFrame=0;lastTime=0;if(saved.theme.network&&saved.theme.motion&&!reducedMotion.matches&&!document.hidden)networkFrame=requestAnimationFrame(animateNetwork);else if(ctx)drawNetwork(0,false)}
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(sizeNetwork,120)});
document.addEventListener('visibilitychange',updateNetwork);reducedMotion.addEventListener?.('change',()=>{updateNetwork();document.querySelectorAll('.reveal').forEach(el=>el.dataset.reveal='visible')});
