window.FI_IMPORT=async function(data){if(!data||data.schemaVersion!==2||!Array.isArray(data.reports))throw new Error('اختر ملف تصدير إعدادات صناعيو المستقبل.');const origin='https://future-industrialists-report-review.azlar.chatgpt.site';function normalizeImported(v){if(typeof v==='string'&&v.startsWith('/api/'))return origin+v;if(Array.isArray(v))return v.map(normalizeImported);if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,x])=>[k.startsWith('/api/')?origin+k:k,normalizeImported(x)]));return v}data=normalizeImported(data);const allowed=['theme','headers','stats','visits','factories','partners','partnerRegistryConfigured','partnerSources','print','reports','orders','sources','intakes','automation','deletedReports'];for(const key of allowed)if(data[key]!==undefined)saved[key]=data[key];persist();state.view='admin';render();for(const report of reportRecords())if(!saved.deletedReports[report.id]){const ok=await syncRemoteReport(report);if(!ok)throw new Error(lastSaveError)}toast('تم استيراد التقارير والتعديلات ونشرها على GitHub.');};


